/**
 * Parses a raw component path string of the form `path`, `path#ExportName`,
 * mirroring the runtime behaviour of Payload's `parsePayloadComponent`.
 *
 * When `overrideExportName` is provided (the object form's `exportName`
 * property) it takes precedence over any `#` suffix and marks the export as
 * explicit.
 */
export function parseComponentPath(
  raw: string,
  overrideExportName?: string,
): ParsedComponent {
  let path: string
  let exportName: string
  let exportNameExplicit: boolean

  if (raw.includes('#')) {
    const hashIndex = raw.indexOf('#')
    path = raw.slice(0, hashIndex)
    exportName = raw.slice(hashIndex + 1)
    exportNameExplicit = true
  } else {
    path = raw
    exportName = 'default'
    exportNameExplicit = false
  }

  if (typeof overrideExportName === 'string' && overrideExportName.length > 0) {
    exportName = overrideExportName
    exportNameExplicit = true
  }

  return { exportName, exportNameExplicit, path }
}
