import type { PluginContext } from './types.js'

const RESOLVE_EXTENSIONS = ['.ts', '.tsx', '.d.ts', '.js', '.jsx', '.mjs', '.cjs']
const INDEX_EXTENSIONS = ['.ts', '.tsx', '.d.ts', '.js', '.jsx', '.mjs', '.cjs']

function toPosix(p: string): string {
  return p.replace(/\\/g, '/')
}

/**
 * Given an absolute path with no extension (or a directory), try the various
 * source-file extensions and `index.*` files, returning the first that exists.
 */
function resolveFileCandidates(ctx: PluginContext, absPath: string): string | undefined {
  // If the path already points at an existing file (it carried its own
  // extension) use it directly.
  if (ctx.fileExists(absPath) && path.extname(absPath) !== '') {
    return absPath
  }

  for (const ext of RESOLVE_EXTENSIONS) {
    const candidate = absPath + ext
    if (ctx.fileExists(candidate)) {
      return candidate
    }
  }

  // Fall back to a directory index file.
  for (const ext of INDEX_EXTENSIONS) {
    const candidate = path.join(absPath, 'index' + ext)
    if (ctx.fileExists(candidate)) {
      return candidate
    }
  }

  // Last resort: the path may already be an exact file with a non-standard
  // extension.
  if (ctx.fileExists(absPath)) {
    return absPath
  }

  return undefined
}

/**
 * Expands a tsconfig `paths` alias (e.g. `@/components/Foo`) into an absolute
 * filesystem path prefix (without extension), or returns `null` when the
 * specifier does not match any alias.
 */
export function expandAlias(ctx: PluginContext, specifier: string): null | string {
  const { baseUrl, paths } = ctx.compilerOptions
  if (!paths) {
    return null
  }

  const base = baseUrl ? path.resolve(ctx.projectRoot, baseUrl) : ctx.projectRoot

  for (const key of Object.keys(paths)) {
    const targets = paths[key]
    if (!targets || targets.length === 0) {
      continue
    }
    const target = targets[0]!

    if (key.endsWith('/*')) {
      const prefix = key.slice(0, -1) // keep trailing slash, e.g. "@/"
      if (specifier.startsWith(prefix) || specifier === key.slice(0, -2)) {
        const rest = specifier.startsWith(prefix) ? specifier.slice(prefix.length) : ''
        const targetPrefix = target.endsWith('/*') ? target.slice(0, -1) : target
        return path.resolve(base, targetPrefix + rest)
      }
    } else if (specifier === key) {
      return path.resolve(base, target)
    }
  }

  return null
