  const dir = toPosix(dirPart)

  if (dir === '' || dir === '/') {
    // A bare "/" (or empty) resolves to the project root / base dir.
    return ctx.projectRoot
  }

  if (dir.startsWith('/')) {
    return path.join(ctx.projectRoot, dir)
  }

  if (dir.startsWith('.')) {
    return path.join(path.dirname(containingFile), dir)
  }

  const aliasBase = expandAlias(ctx, dir.endsWith('/') ? dir.slice(0, -1) : dir)
  if (aliasBase) {
    return aliasBase
  }

  return undefined
}
