 * Computes the Levenshtein edit distance between two strings.
 */
function editDistance(a: string, b: string): number {
  const m = a.length
  const n = b.length
  if (m === 0) {
    return n
  }
  if (n === 0) {
    return m
  }

  let previous = new Array<number>(n + 1)
  let current = new Array<number>(n + 1)

  for (let j = 0; j <= n; j++) {
    previous[j] = j
  }

  for (let i = 1; i <= m; i++) {
    current[0] = i
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1
      current[j] = Math.min(previous[j]! + 1, current[j - 1]! + 1, previous[j - 1]! + cost)
    }
    const swap = previous
    previous = current
    current = swap
  }

  return previous[n]!
}

/**
 * Finds the closest matching candidate to `name` within a reasonable edit
 * distance, mirroring TypeScript's own "Did you mean" heuristic (distance no
 * more than a fifth of the longer name's length, rounded up, minimum 1).
 */
export function findClosestSuggestion(name: string, candidates: string[]): string | undefined {
  let best: string | undefined
  let bestDistance = Number.POSITIVE_INFINITY

  for (const candidate of candidates) {
    const lower = name.toLowerCase()
    const candLower = candidate.toLowerCase()
    const maxAllowed = Math.max(1, Math.floor(Math.max(name.length, candidate.length) / 5) + 1)

    // Prefer a case-insensitive exact match immediately.
    if (lower === candLower) {
      return candidate
    }

    const distance = editDistance(name, candidate)
    if (distance <= maxAllowed && distance < bestDistance) {
      best = candidate
      bestDistance = distance
    }
  }

  return best
}
