/**
 * Produces completions for a Payload component string literal at `position`,
 * or `undefined` when the position is not inside such a string.
 */
export function getComponentCompletions(
  ctx: PluginContext,
  sourceFile: tsModule.SourceFile,
  position: number,
): tsModule.WithMetadata<tsModule.CompletionInfo> | undefined {
  const target = getComponentStringAtPosition(ctx, sourceFile, position)
  if (!target) {
    return undefined
  }

  const content = target.node.text
  const contentStart = target.node.getStart() + 1
  const cursorOffset = Math.max(0, Math.min(content.length, position - contentStart))
  const before = content.slice(0, cursorOffset)

  // Export-name completions.
  if (target.kind === 'objectExport') {
    if (!target.siblingPathNode) {
      return undefined
    }
    const pathValue = target.siblingPathNode.text.split('#')[0]!
    return buildExportCompletions(ctx, pathValue, sourceFile.fileName)
  }

  const hashIndex = content.indexOf('#')
  const cursorAfterHash = hashIndex !== -1 && cursorOffset > hashIndex
  if (cursorAfterHash) {
    const pathValue = content.slice(0, hashIndex)
    return buildExportCompletions(ctx, pathValue, sourceFile.fileName)
  }

  // Path-segment completions.
  return buildPathCompletions(ctx, before, sourceFile.fileName)
}

function buildExportCompletions(
  ctx: PluginContext,
  pathValue: string,
  containingFile: string,
): tsModule.WithMetadata<tsModule.CompletionInfo> | undefined {
  const resolvedFile = resolveComponentFile(ctx, pathValue, containingFile)
  if (!resolvedFile) {
    return emptyCompletions(ctx)
  }

  const moduleExports = getModuleExports(ctx, resolvedFile)
  const entries: tsModule.CompletionEntry[] = moduleExports.names.map((name) => ({
    kind: ctx.ts.ScriptElementKind.alias,
    kindModifiers: '',
    name,
    sortText: name,
  }))

  return completions(ctx, entries)
}

function buildPathCompletions(
  ctx: PluginContext,
  before: string,
  containingFile: string,
): tsModule.WithMetadata<tsModule.CompletionInfo> | undefined {
  const lastSlash = before.lastIndexOf('/')
  const dirPart = lastSlash === -1 ? '' : before.slice(0, lastSlash + 1)

  const dir = resolveDirectory(ctx, dirPart, containingFile)
  if (!dir) {
    return emptyCompletions(ctx)
  }

  const entries: tsModule.CompletionEntry[] = []
  for (const entry of ctx.getDirectoryEntries(dir)) {
    if (entry.name.startsWith('.')) {
      continue
    }
    entries.push({
      kind: entry.isDirectory
        ? ctx.ts.ScriptElementKind.directory
        : ctx.ts.ScriptElementKind.scriptElement,
      kindModifiers: '',
      name: entry.name,
      sortText: `${entry.isDirectory ? '0' : '1'}${entry.name}`,
    })
  }

  return completions(ctx, entries)
}

