  ctx: PluginContext,
  entries: tsModule.CompletionEntry[],
): tsModule.WithMetadata<tsModule.CompletionInfo> {
  return {
    entries,
    isGlobalCompletion: false,
    isMemberCompletion: false,
    isNewIdentifierLocation: true,
  }
}

