function getPropertyName(
  ts: typeof tsModule,
  property: tsModule.PropertyAssignment,
): string | undefined {
  const name = property.name
  if (ts.isIdentifier(name) || ts.isStringLiteral(name)) {
    return name.text
  }
  return undefined
}

function getSiblingExportName(
  ctx: PluginContext,
  pathNode: tsModule.StringLiteralLike,
): string | undefined {
  const { ts } = ctx
  const objectNode = pathNode.parent?.parent
  if (!objectNode || !ts.isObjectLiteralExpression(objectNode)) {
    return undefined
  }
  for (const property of objectNode.properties) {
    if (
      ts.isPropertyAssignment(property) &&
      getPropertyName(ts, property) === 'exportName' &&
      (ts.isStringLiteral(property.initializer) ||
        ts.isNoSubstitutionTemplateLiteral(property.initializer))
    ) {
      return property.initializer.text
    }
  }
  return undefined
}

/**
 * Resolves go-to-definition for a Payload component string literal at
 * `position`, pointing at the referenced export.
 */
export function getComponentDefinition(
  ctx: PluginContext,
  sourceFile: tsModule.SourceFile,
  position: number,
): tsModule.DefinitionInfoAndBoundSpan | undefined {
  const target = getComponentStringAtPosition(ctx, sourceFile, position)
  if (!target) {
    return undefined
  }

  let pathValue: string
  let overrideExportName: string | undefined

  if (target.kind === 'objectExport') {
    if (!target.siblingPathNode) {
      return undefined
    }
    pathValue = target.siblingPathNode.text
    overrideExportName = target.node.text
  } else if (target.kind === 'objectPath') {
    pathValue = target.node.text
    overrideExportName = getSiblingExportName(ctx, target.node)
  } else {
    pathValue = target.node.text
  }

  const parsed = parseComponentPath(pathValue, overrideExportName)
  const resolvedFile = resolveComponentFile(ctx, parsed.path, sourceFile.fileName)
  if (!resolvedFile) {
    return undefined
  }

  const moduleExports = getModuleExports(ctx, resolvedFile)
  const location = moduleExports.locations.get(parsed.exportName)

  const definition: tsModule.DefinitionInfo = {
    containerKind: ctx.ts.ScriptElementKind.moduleElement,
    containerName: '',
    fileName: location?.fileName ?? resolvedFile,
    kind: ctx.ts.ScriptElementKind.alias,
    name: parsed.exportName,
    textSpan: {
      length: location?.length ?? 0,
      start: location?.start ?? 0,
    },
  }

  return {
    definitions: [definition],
    textSpan: {
      length: target.node.text.length,
      start: target.node.getStart() + 1,
    },
  }
