function pluginInit(modules: { typescript: typeof tsModule }): {
  create(info: tsModule.server.PluginCreateInfo): tsModule.LanguageService
} {
  const ts = modules.typescript

  function create(info: tsModule.server.PluginCreateInfo): tsModule.LanguageService {
    const base = info.languageService

    // Build a proxy over the base language service, delegating everything and
    // overriding only the methods we enhance.
    const proxy = Object.create(null) as tsModule.LanguageService
    for (const key of Object.keys(base) as (keyof tsModule.LanguageService)[]) {
      const member = base[key]
      if (typeof member === 'function') {
        // @ts-expect-error - generic delegation
        proxy[key] = (...args: unknown[]) => (member as (...a: unknown[]) => unknown).apply(base, args)
      } else {
        // @ts-expect-error - generic delegation
        proxy[key] = member
      }
    }

    const buildContext = (): PluginContext | undefined => {
      const program = base.getProgram()
      if (!program) {
        return undefined
      }
      return createPluginContext(ts, info, program)
    }

    proxy.getSemanticDiagnostics = (fileName: string): tsModule.Diagnostic[] => {
      const prior = base.getSemanticDiagnostics(fileName)
      try {
        const ctx = buildContext()
        if (!ctx) {
          return prior
        }
        const sourceFile = ctx.program.getSourceFile(fileName)
        if (!sourceFile) {
          return prior
        }
        const extra = getComponentDiagnostics(ctx, sourceFile)
        return extra.length > 0 ? [...prior, ...extra] : prior
      } catch {
        return prior
      }
    }

    proxy.getCompletionsAtPosition = (
      fileName: string,
      position: number,
      options: tsModule.GetCompletionsAtPositionOptions | undefined,
      formattingSettings?: tsModule.FormatCodeSettings,
    ): tsModule.WithMetadata<tsModule.CompletionInfo> | undefined => {
      try {
        const ctx = buildContext()
        if (ctx) {
          const sourceFile = ctx.program.getSourceFile(fileName)
          if (sourceFile) {
            const result = getComponentCompletions(ctx, sourceFile, position)
            if (result) {
              return result
            }
          }
        }
      } catch {
        // fall through to base
      }
      return base.getCompletionsAtPosition(fileName, position, options, formattingSettings)
    }

    proxy.getDefinitionAndBoundSpan = (
      fileName: string,
      position: number,
    ): tsModule.DefinitionInfoAndBoundSpan | undefined => {
      try {
        const ctx = buildContext()
        if (ctx) {
          const sourceFile = ctx.program.getSourceFile(fileName)
          if (sourceFile) {
