    getDirectories: (d) => (sys && sys.getDirectories ? sys.getDirectories(d) : []),
    readFile,
    realpath: sys && sys.realpath ? (p) => sys.realpath!(p) : undefined,
    useCaseSensitiveFileNames: sys ? sys.useCaseSensitiveFileNames : true,
  }

  return {
    checker: program.getTypeChecker(),
    compilerOptions: program.getCompilerOptions(),
    fileExists,
    getDirectoryEntries,
    moduleResolutionHost,
    program,
    projectRoot,
    readFile,
    ts,
  }
