import { isComponentType } from './detect.js'
import type { PluginContext } from './types.js'

/**
 * How a component string literal at a given position is being used.
 */
export type ComponentStringKind = 'objectExport' | 'objectPath' | 'stringPath'

export interface ComponentStringAtPosition {
  kind: ComponentStringKind
  node: tsModule.StringLiteralLike
  /** For `objectExport`, the sibling `path` string literal (if any). */
  siblingPathNode?: tsModule.StringLiteralLike
}

function isStringLiteralLike(
  ts: typeof tsModule,
  node: tsModule.Node,
): node is tsModule.StringLiteralLike {
  return ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)
}

/**
 * Finds the innermost string literal that contains `position`.
 */
function findStringLiteralAt(
  ts: typeof tsModule,
  sourceFile: tsModule.SourceFile,
  position: number,
): tsModule.StringLiteralLike | undefined {
  let found: tsModule.StringLiteralLike | undefined

  const visit = (node: tsModule.Node): void => {
    if (position < node.getFullStart() || position > node.getEnd()) {
      return
    }
    if (isStringLiteralLike(ts, node)) {
      // Only when the cursor is inside the quotes (or at the closing quote).
      if (position >= node.getStart() + 1 && position <= node.getEnd()) {
        found = node
      }
    }
    node.forEachChild(visit)
  }

  visit(sourceFile)
  return found
}

function getPropertyName(
  ts: typeof tsModule,
  property: tsModule.PropertyAssignment,
): string | undefined {
  const name = property.name
  if (ts.isIdentifier(name) || ts.isStringLiteral(name)) {
    return name.text
  }
  return undefined
}

function findSiblingProperty(
  ts: typeof tsModule,
  objectNode: tsModule.ObjectLiteralExpression,
  propertyName: string,
): tsModule.StringLiteralLike | undefined {
  for (const property of objectNode.properties) {
    if (ts.isPropertyAssignment(property) && getPropertyName(ts, property) === propertyName) {
      if (isStringLiteralLike(ts, property.initializer)) {
        return property.initializer
      }
    }
  }
  return undefined
}

/**
 * Locates and classifies a Payload component string literal at `position`.
 * Returns `undefined` when the position is not inside a component string.
 */
export function getComponentStringAtPosition(
  ctx: PluginContext,
  sourceFile: tsModule.SourceFile,
  position: number,
): ComponentStringAtPosition | undefined {
  const { checker, ts } = ctx
  const node = findStringLiteralAt(ts, sourceFile, position)
  if (!node) {
    return undefined
  }

  const parent = node.parent
  if (parent && ts.isPropertyAssignment(parent) && parent.initializer === node) {
    const propName = getPropertyName(ts, parent)
    const objectNode = parent.parent
    if (
      (propName === 'path' || propName === 'exportName') &&
      objectNode &&
      ts.isObjectLiteralExpression(objectNode) &&
      isComponentType(ctx, checker.getContextualType(objectNode))
    ) {
      if (propName === 'path') {
        return { kind: 'objectPath', node }
      }
      return {
        kind: 'objectExport',
        node,
        siblingPathNode: findSiblingProperty(ts, objectNode, 'path'),
      }
    }
    return undefined
  }

  if (isComponentType(ctx, checker.getContextualType(node))) {
    return { kind: 'stringPath', node }
  }

  return undefined
}
